dtsPropsFor.CurveChart:
/** The household's money-vs-pay story. */
  analysis: { points: { earnings: number; netIncome: number }[]; cliffs: { startEarnings: number; endEarnings: number; drop: number; programsLost: string[] }[]; dangerZones: { startEarnings: number; endEarnings: number | null; peakNet: number }[]; currentEarnings?: number; currentNet?: number };
  /** How pay reads on the x-axis and in the drop cards. Default "year". */
  unit?: "hour" | "month" | "year";
  /** Hours per week, when unit is "hour". Default 40. */
  hoursPerWeek?: number;
  /** Show the "you are here" dot. Default true. */
  showCurrent?: boolean;
  /** A full-time-minimum-wage reference marker: a dashed line at full-time-minimum earnings, plus a plain label shown below the chart. Real-world context only; drawn only when the earnings fall inside the charted pay range. */
  minWageLine?: { earnings: number; label: string };

dtsPropsFor.Legend:
/** Heading above the scale. */
  title?: string;
  /** The scale steps, light to dark. Build them with rampLegendItems(values) so they match the map. */
  items: { color: string; label: string }[];

dtsPropsFor.ChoroplethMap:
/** Two-letter USPS code to the value to shade that state by. */
  values: Partial<Record<string, number>>;
  /** Currently selected state (USPS code), if any. */
  selected?: string | null;
  /** Word for what the value measures, used in each state's label. */
  valueLabel?: string;
  /** How to render a value in a state's accessible label. */
  formatValue?: (value: number) => string;
  onSelect?: (usps: string) => void;
